create or replace function public.communication_open_contact(p_contact_user_id uuid, p_contact_name text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare v_conversation_id uuid; v_name text; begin if auth.uid() is null then raise exception 'Authentication is required'; end if; if p_contact_user_id is null or p_contact_user_id = auth.uid() then raise exception 'A valid different recipient is required'; end if; select coalesce(nullif(trim(p_contact_name),''),nullif(trim(p.full_name),''),p.email,'Avelixa User') into v_name from public.profiles p where p.id=p_contact_user_id; if v_name is null then raise exception 'Avelixa user not found'; end if; insert into public.user_contacts(user_id,contact_user_id,contact_name) values(auth.uid(),p_contact_user_id,v_name) on conflict(user_id,contact_user_id) do update set contact_name=coalesce(nullif(trim(excluded.contact_name),''),public.user_contacts.contact_name); v_conversation_id := public.get_or_create_direct_conversation(p_recipient_id:=p_contact_user_id); return v_conversation_id; end; $$; revoke all on function public.communication_open_contact(uuid,text) from public; grant execute on function public.communication_open_contact(uuid,text) to authenticated;